const A=window.ASSETS||{};
const asset=(path)=>A[path]||'';
const main=document.getElementById('main');
function home(){return `<section class="hero"><h1 class="sr-only">Resultados reales en cada rincón</h1><a class="hero-link" href="#tienda"><img src="${asset('Propuestas web/Inicio/1 Archer.png')}" alt="Archer. Resultados reales en cada rincón. Productos de limpieza para tu hogar."><span class="hero-caption"><strong>Un hogar más limpio.<br>Un cuidado para todos.</strong><span class="button">Compra ahora ↗</span></span></a><div class="hero-bottom"><span>Tu hogar, tu bienestar. Nuestras marcas.</span><a href="#productos">Conócelas ↗</a></div></section><div class="shell trust-line"><span><i>✧</i> Fabricación boliviana</span><span><i>◇</i> El formato que necesitas</span><span><i>↗</i> Atención por WhatsApp</span></div><section class="section shell"><div class="section-heading"><div><span class="eyebrow">PARA CADA PARTE DE TU DÍA</span><h2>Un cuidado para todo.</h2></div><a class="text-link" href="#tienda">Explorar productos ↗</a></div><div class="category-grid">${[['2.1 Cuidado del hogar.jpeg','Cuidado del hogar','tienda?categoria=hogar'],['2.2 Cuidado personal.png','Cuidado personal','tienda?categoria=personal'],['2.3 Institucional.png','Institucional','institucional']].map(([im,name,to])=>`<a href="#${to}" class="category-card"><img src="${asset('Propuestas web/Inicio/'+im)}" alt="${name}" loading="lazy"><span class="category-label">${name}<b aria-hidden="true">↗</b></span></a>`).join('')}</div></section><section class="promo"><div class="shell"><span class="eyebrow">TU COMPRA WEB RINDE MÁS</span><h2>PRO<em>MOCIONES.</em></h2><a class="promo-direct" href="#tienda"><div><span class="eyebrow">TU HOGAR. TUS FAVORITOS.</span><h3>Compra directo.<br><em>Cuida más.</em></h3><p>Todo lo que necesitas, en el formato que buscas y con tu precio web.</p><span class="button">Elegir mis productos ↗</span></div><div class="promo-packs" aria-hidden="true"><img src="${C.find(p=>p.id==='vajillero').image}" alt=""><img src="${C.find(p=>p.id==='classic-shampoo').image}" alt=""><img src="${C.find(p=>p.id==='antigrasa').image}" alt=""></div></a></div></section><div class="shell brand-strip">${[['Archer','Archer-Logo.png'],['Classic','Classic-Logo.png'],['Biosilk','Logo-Biosilk.png'],['Supremo','LOGO-SUPREMOP-SHAMPOO.png']].map(([name,file])=>`<a href="#tienda?marca=${name}"><img src="${asset('Propuestas web/Productos/1 Nuestras marcas/'+file)}" alt="${name}" loading="lazy"></a>`).join('')}</div>`}
const C=window.CATALOG,CFG=window.SHOP_CONFIG,S=window.ShopCore;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=v=>S.finalCents(v.listCents);
const reference=v=>S.referenceCents(v.listCents,CFG.referenceMarkupPercent);
const money=S.money;
let cart=[];try{cart=S.normalizeCart(JSON.parse(localStorage.getItem('archer-cart')||'[]'),C)}catch{}
let carouselTimer,brandIndex=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,selectedProduct=null,selectedVariant=null,orderDraft=null;
const brandFiles={Archer:'Archer-Logo.png',Classic:'Classic-Logo.png',Biosilk:'Logo-Biosilk.png',Supremo:'LOGO-SUPREMOP-SHAMPOO.png'};
const brandLogo=name=>asset('Propuestas web/Productos/1 Nuestras marcas/'+brandFiles[name]);
const productDialog=document.getElementById('product-dialog'),cartDialog=document.getElementById('cart-dialog');
const wa=text=>'https://wa.me/'+CFG.whatsapp+'?text='+encodeURIComponent(text);
const lookup=id=>C.find(p=>p.variants.some(v=>v.id===id));
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
function saveCart(){try{localStorage.setItem('archer-cart',JSON.stringify(cart))}catch{}const count=S.totals(cart,C,CFG.referenceMarkupPercent).count;document.getElementById('cart-count').textContent=count;document.querySelector('.cart-toggle').setAttribute('aria-label',`Abrir carrito, ${count} productos`)}
function addCart(variantId,quantity=1){if(!lookup(variantId)||!Number.isInteger(quantity)||quantity<1||quantity>99)return false;const row=cart.find(r=>r.variantId===variantId);if(row)row.quantity=Math.min(99,row.quantity+quantity);else cart.push({variantId,quantity});saveCart();toast('Producto añadido a tu carrito');return true}
function card(p,institutional=false){const variants=p.variants.filter(v=>!institutional||v.liters===5),priced=variants.filter(v=>v.listCents!==null).sort((a,b)=>a.listCents-b.listCents),v=priced[0]||variants[0];return `<article class="product-card"><button class="product-image" data-product="${p.id}" ${institutional?'data-institutional="true"':''} aria-label="Elegir presentación de ${esc(p.brand+' '+p.name)}"><span class="discount">${v.listCents===null?'Consultar':'PRECIO WEB'}</span><img src="${institutional?variants[0].image:p.image}" alt="${esc(p.brand+' '+p.name)}" loading="lazy"><span class="image-open" aria-hidden="true">+</span></button><div class="product-info"><span class="product-brand">${p.brand}${institutional?' · FORMATO 5 L':''}</span><h3><button data-product="${p.id}" ${institutional?'data-institutional="true"':''}>${p.name}</button></h3><p>${institutional?(p.use||p.description):variants.length+' '+(variants.length===1?'presentación':'presentaciones')}</p><div class="card-price">${v.listCents===null?'<b>Solicitar cotización</b>':`<div><span>Desde</span><b>${money(price(v))}</b></div><span class="reference-price">Ref. ${money(reference(v))}</span>`}</div><button class="card-choose" data-product="${p.id}" ${institutional?'data-institutional="true"':''}>Elegir presentación <span aria-hidden="true">↗</span></button></div></article>`}
function shop(params){const cat=params.get('categoria')||'todos',brand=params.get('marca')||'todas';return `<section class="shop-heading"><div class="shell"><div class="breadcrumb"><a href="#inicio">Inicio</a><span>/</span>Tienda</div><div class="section-heading"><div><span class="eyebrow">EL CUIDADO QUE BUSCAS, EN UN SOLO LUGAR</span><h1>Todo listo para<br><em>tu día a día.</em></h1></div><div class="offer-stamp"><strong>WEB</strong><span>COMPRA DIRECTO<br>elige tu presentación</span></div></div></div></section><section class="shell shop-section"><div class="shop-toolbar"><div class="category-tabs" role="group" aria-label="Categoría de productos">${[['todos','Todos'],['hogar','Hogar'],['personal','Cuidado personal'],['institucional','Institucional · 5 L']].map(([value,label])=>`<button data-category="${value}" class="${cat===value?'active':''}" aria-pressed="${cat===value}">${label}</button>`).join('')}</div><label class="search-field"><svg viewBox="0 0 24 24" width="19" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="search" type="search" placeholder="¿Qué necesitas hoy?" aria-label="Buscar productos"></label></div><div class="shop-meta"><span id="result-count" role="status"></span><div><label>Marca <select id="brand-filter"><option value="todas">Todas las marcas</option>${Object.keys(brandFiles).map(n=>`<option ${n===brand?'selected':''}>${n}</option>`).join('')}</select></label><label>Ordenar <select id="sort-filter"><option value="recommended">Recomendados</option><option value="low">Menor precio</option><option value="high">Mayor precio</option><option value="name">Nombre A–Z</option></select></label></div></div><div class="product-grid" id="product-grid"></div><p class="catalog-note">Precios por presentación, en bolivianos. La referencia se calcula un 30 % por encima del precio web; no representa un precio anterior de venta. Envío y disponibilidad se confirman por WhatsApp.</p></section>`}
let shopCategory='todos';
function filterShop(){const query=document.getElementById('search').value.trim().normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase(),brand=document.getElementById('brand-filter').value,sort=document.getElementById('sort-filter').value;let list=C.filter(p=>(shopCategory==='todos'||(shopCategory==='institucional'?p.institutional:p.category===shopCategory))&&(brand==='todas'||p.brand===brand)&&[p.name,p.brand,p.description,...p.variants.map(v=>v.label)].join(' ').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(query));const min=p=>Math.min(...p.variants.filter(v=>v.listCents!==null&&(shopCategory!=='institucional'||v.liters===5)).map(v=>price(v)));if(sort==='low')list.sort((a,b)=>min(a)-min(b));if(sort==='high')list.sort((a,b)=>min(b)-min(a));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));document.getElementById('result-count').textContent=list.length+(list.length===1?' familia de productos':' familias de productos');document.getElementById('product-grid').innerHTML=list.length?list.map(p=>card(p,shopCategory==='institucional')).join(''):`<div class="empty-state"><h2>No encontramos ese producto.</h2><p>Prueba con otra palabra o cambia los filtros.</p><button class="button navy" id="reset-filters">Ver todos los productos</button></div>`;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===shopCategory);b.setAttribute('aria-pressed',b.dataset.category===shopCategory)})}
function openProduct(id,institutional=false){const p=C.find(p=>p.id===id);if(!p)return;selectedProduct=p;selectedVariant=p.variants.find(v=>!institutional||v.liters===5)||p.variants[0];productDialog.innerHTML=`<button class="dialog-close icon-button" data-close aria-label="Cerrar producto">×</button><div class="product-detail"><div class="detail-art"><span class="discount">PRECIO WEB</span><img id="detail-image" src="${selectedVariant.image}" alt="${esc(p.name)}"><span class="detail-art-caption">Imagen referencial de la familia · ${p.brand} ${p.name}</span></div><div class="detail-content"><span class="eyebrow">${p.brand} / ${p.category==='hogar'?'CUIDADO DEL HOGAR':'CUIDADO PERSONAL'}</span><h2 id="product-title">${p.name}</h2><p>${p.description}</p><label class="field">Elige tu presentación<select id="variant-select">${p.variants.map(v=>`<option value="${v.id}" ${v.id===selectedVariant.id?'selected':''}>${esc(v.label)}${v.listCents===null?' · Consultar precio':''}</option>`).join('')}</select></label><div id="detail-price"></div><div class="add-line"><label class="quantity-label">Cantidad<input id="product-qty" type="number" min="1" max="99" step="1" value="1" inputmode="numeric"></label><button class="button" id="add-product">Añadir al carrito <span aria-hidden="true">+</span></button></div><p class="micro">Precio por presentación seleccionada. La entrega y el pago se coordinan por WhatsApp.</p><details class="product-details"><summary>Información del producto</summary><dl><div><dt>Marca</dt><dd>${p.brand}</dd></div><div><dt>Referencia</dt><dd>Catálogo de agosto de 2026</dd></div></dl><p>${p.use||'Consulta las instrucciones, precauciones y compatibilidad en la etiqueta del producto.'}</p><p>Para fichas técnicas y requerimientos de empresas, <a href="#institucional" data-close-link>contacta a nuestro equipo comercial</a>.</p></details></div></div>`;updateVariant();if(!productDialog.open)productDialog.showModal()}
function updateVariant(){const v=selectedVariant;productDialog.querySelector('.detail-art .discount').textContent=v.listCents===null?'Consultar':'PRECIO WEB';document.getElementById('detail-image').src=v.image;document.getElementById('detail-image').alt=selectedProduct.brand+' '+selectedProduct.name+' '+v.label;document.getElementById('detail-price').innerHTML=v.listCents===null?'<div class="detail-price"><strong>Precio por cotizar</strong></div><p class="micro">Esta presentación no tiene un precio visible en el catálogo. Puedes incluirla en tu solicitud; no se sumará como un producto gratuito.</p>':`<div class="detail-price"><strong>${money(price(v))}</strong><div><span>Referencia calculada: ${money(reference(v))}</span><b>Tu precio web</b></div></div>`;document.getElementById('add-product').innerHTML=v.listCents===null?'Añadir a mi solicitud +':'Añadir al carrito +'}
function cartLines(){return S.lines(cart,C,CFG.referenceMarkupPercent).map(r=>`<article class="cart-line"><img src="${r.variant.image}" alt="${esc(r.product.name)}"><div><span class="product-brand">${r.product.brand}</span><h3>${r.product.name}</h3><p>${r.variant.label}</p><div class="quantity-controls"><button data-qty="${r.variantId}" data-delta="-1" ${r.quantity===1?'disabled':''} aria-label="Reducir cantidad de ${esc(r.product.name)}">−</button><span>${r.quantity}</span><button data-qty="${r.variantId}" data-delta="1" ${r.quantity===99?'disabled':''} aria-label="Aumentar cantidad de ${esc(r.product.name)}">+</button></div></div><div class="cart-line-end"><button data-remove="${r.variantId}" aria-label="Eliminar ${esc(r.product.name+' '+r.variant.label)}" class="remove">Eliminar</button><strong>${r.unitCents===null?'Por cotizar':money(r.unitCents*r.quantity)}</strong></div></article>`).join('')}
function summary(){const t=S.totals(cart,C,CFG.referenceMarkupPercent);return `<div class="totals"><div><span>Precio web de productos</span><span>${money(t.totalCents)}</span></div><div><span>Envío</span><span>Por coordinar</span></div><div class="total"><strong>${t.hasQuote?'Subtotal conocido':'Total de productos'}</strong><strong>${money(t.totalCents)}</strong></div>${t.hasQuote?'<p class="micro">Incluye presentaciones con precio por cotizar. El total final se confirmará por WhatsApp.</p>':''}<p class="micro">El costo de envío no está incluido. Pago pendiente de coordinación.</p></div>`}
function openCart(){cartDialog.innerHTML=`<div class="drawer-head"><div><span class="eyebrow">BUENAS ELECCIONES</span><h2 id="cart-title">Tu carrito <span>(${S.totals(cart,C).count})</span></h2></div><button class="icon-button" data-close aria-label="Cerrar carrito">×</button></div>${cart.length?`<div class="cart-lines">${cartLines()}</div><div class="drawer-bottom">${summary()}<a class="button full" href="#pedido" data-checkout>Continuar con mi pedido ↗</a><button class="text-button" data-close>Seguir comprando</button></div>`:'<div class="empty-state"><span class="empty-icon">◌</span><h3>Aquí empieza tu próxima compra.</h3><p>Elige tus productos y su presentación favorita.</p><a class="button" href="#tienda" data-checkout>Explorar la tienda ↗</a></div>'}`;if(!cartDialog.open)cartDialog.showModal()}
function checkout(){if(!cart.length)return `<section class="shell section empty-state"><h1>Tu carrito está vacío.</h1><p>Elige algunos productos antes de preparar tu pedido.</p><a class="button" href="#tienda">Ir a la tienda ↗</a></section>`;return `<section class="shell section checkout"><div class="breadcrumb"><a href="#tienda">Tienda</a><span>/</span>Tu pedido</div><span class="eyebrow">UN PASO MÁS CERCA</span><h1>¿A dónde lo llevamos?</h1><div class="checkout-grid"><form id="order-form"><section class="form-section"><h2><span>01</span> Tus datos</h2><div class="form-grid"><label class="field">Nombre completo<input name="name" required autocomplete="name" maxlength="100"></label><label class="field">Celular / WhatsApp<input name="phone" type="tel" required autocomplete="tel" pattern="[+0-9 ()-]{8,20}" maxlength="20" title="Escribe un número de 8 a 20 caracteres." placeholder="Ej. 77226763"></label></div></section><section class="form-section"><h2><span>02</span> Entrega</h2><div class="form-grid"><label class="field">Departamento<select name="department" required><option value="">Selecciona</option>${['Cochabamba','La Paz','Santa Cruz','Chuquisaca','Oruro','Potosí','Tarija','Beni','Pando'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Ciudad o municipio<input name="city" required autocomplete="address-level2" maxlength="80"></label><label class="field wide">Dirección de entrega<input name="address" required autocomplete="street-address" maxlength="240" placeholder="Calle, número, zona, edificio…"></label><label class="field wide">Ubicación o referencia precisa<textarea name="location" required maxlength="400" rows="2" placeholder="Pega tu enlace de Google Maps o escribe una referencia para llegar."></textarea></label><label class="field wide">Indicaciones adicionales <span>(opcional)</span><textarea name="notes" maxlength="350" rows="2" placeholder="Piso, timbre, horario para recibir…"></textarea></label></div><p class="micro">Confirmaremos cobertura, costo y fecha de entrega antes del pago.</p></section><section class="form-section"><h2><span>03</span> Facturación</h2><label class="field">¿Necesitas factura?<select id="invoice" name="invoice"><option value="si">Sí, con estos datos</option><option value="no">No solicitar por ahora</option></select></label><div class="form-grid" id="invoice-fields"><label class="field">Nombre o razón social<input name="business" required maxlength="120"></label><label class="field">NIT / CI<input name="taxId" required maxlength="30" pattern="[A-Za-z0-9 -]{3,30}" title="Escribe tu NIT o CI, con complemento si corresponde."></label></div></section><p class="privacy-note">Revisarás tu pedido antes de compartirlo. Al continuar a WhatsApp, enviarás tus datos de contacto, facturación y entrega al equipo de Archer (77226763). Este sitio no procesa pagos.</p><button type="submit" class="button full">Revisar mi pedido ↗</button></form><aside class="order-aside"><h2>Tu selección</h2><div class="order-mini">${S.lines(cart,C,CFG.referenceMarkupPercent).map(r=>`<div><img src="${r.variant.image}" alt=""><span><b>${r.product.brand} ${r.product.name}</b><small>${r.variant.label} × ${r.quantity}</small></span><strong>${r.unitCents===null?'Por cotizar':money(r.unitCents*r.quantity)}</strong></div>`).join('')}</div>${summary()}<button class="text-button cart-toggle">Editar carrito</button></aside></div></section>`}
function reviewOrder(data){orderDraft=data;const message=S.orderMessage(cart,C,data,CFG.referenceMarkupPercent);document.getElementById('order-form').innerHTML=`<section class="form-section"><span class="eyebrow">REVISA ANTES DE ENVIAR</span><h2>Todo en orden.</h2><p>Este es el detalle que recibirá nuestro equipo comercial.</p><dl class="review-details"><div><dt>Cliente</dt><dd>${esc(data.name)} · ${esc(data.phone)}</dd></div><div><dt>Entrega</dt><dd>${esc(data.address)}<br>${esc(data.city)}, ${esc(data.department)}</dd></div><div><dt>Ubicación</dt><dd>${esc(data.location)}</dd></div><div><dt>Factura</dt><dd>${data.invoice==='si'?esc(data.business)+' · '+esc(data.taxId):'No solicitada'}</dd></div>${data.notes?`<div><dt>Notas</dt><dd>${esc(data.notes)}</dd></div>`:''}</dl></section><div class="confirmation-note"><b>El pedido aún no se ha enviado.</b><p>Se abrirá WhatsApp con el detalle listo. Envía el mensaje allí para confirmar disponibilidad, entrega y coordinar el pago.</p></div><a class="button full whatsapp" id="send-order" href="${wa(message)}" target="_blank" rel="noopener">Enviar pedido por WhatsApp ↗</a><button type="button" class="text-button" id="edit-order">Volver a editar mis datos</button>`;document.getElementById('order-form').scrollIntoView({behavior:'smooth',block:'start'})}
function restoreOrder(){main.innerHTML=checkout();if(orderDraft){const form=document.getElementById('order-form');for(const [key,val] of Object.entries(orderDraft)){const field=form.elements.namedItem(key);if(field)field.value=val}toggleInvoice()}}
function toggleInvoice(){const sel=document.getElementById('invoice');if(!sel)return;const yes=sel.value==='si';document.getElementById('invoice-fields').hidden=!yes;['business','taxId'].forEach(n=>{document.querySelector(`[name="${n}"]`).required=yes})}

const brands=[
 {name:'Archer',title:'El poder de un\nhogar impecable.',text:'Soluciones para cada rincón. Descubre la línea que acompaña tu limpieza de todos los días.',folder:'2.1 Archer imagen en movimineto',background:'Fondo 1.1.png',bottle:'ARCHER Vajillero Verde 12X1050 ML.png',splash:'Splash 1.png',detail:'limon 1.png',color:'#e6f5fd',art:'3.1 Conoce a Archer.png'},
 {name:'Classic',title:'Cuidado que\nva contigo.',text:'Del cabello a la piel, encuentra tu rutina de bienestar con Classic.',folder:'2.2 Classic imagen en movimiento',background:'Fondo 2.png',bottle:'Shampoo Manzana CLASSIC 950 mL.png',splash:'Splash 1.png',detail:'Manzana 1.png',color:'#edf5e4',art:'3.2 Conoce a Classic.png'},
 {name:'Biosilk',title:'Tu cabello,\ntu mejor versión.',text:'Elige tu fórmula y tu formato. Un cuidado para cada día con Biosilk.',folder:'2.3 Biosilk imagen en movimineto',background:'Fondo 1.2.png',bottle:'BIOLISK Doy Pack Manzanilla 1L.png',splash:'Splash 1.png',detail:'Manzanilla 1.png',color:'#fff8df',art:'3.3 Conoce a Biosilk.png'},
 {name:'Supremo',title:'Bienestar\nque rinde más.',text:'Presentaciones de 1 y 5 litros para acompañar a tu familia y a tu negocio.',folder:'2.4 Supremo imagen en movimiento',background:'Fondo 2.2.png',bottle:'SUPREMO Shampoo Frutilla 1 Lt.png',splash:'Splash 1.png',detail:'Frutilla 1.png',color:'#ffeded',art:'3.4 Conoce a supremo.png'}
];
function brandsPage(){return `<section class="shell brands-intro"><span class="eyebrow">CUATRO MARCAS. UN MISMO COMPROMISO.</span><h1>Encuentra tu <em>favorita.</em></h1><p>Limpieza, frescura y cuidado para cada parte de tu vida.</p></section><section class="brand-experience" aria-roledescription="carrusel" aria-label="Nuestras marcas"><div id="brand-stage"></div><div class="brand-progress" aria-hidden="true"><span></span></div><div class="brand-controls shell"><button class="circle-control" data-brand-prev aria-label="Marca anterior">←</button><div class="brand-tabs">${brands.map((b,i)=>`<button data-brand-index="${i}" aria-label="Ver marca ${b.name}"><img src="${brandLogo(b.name)}" alt="${b.name}"></button>`).join('')}</div><button class="circle-control" data-brand-next aria-label="Siguiente marca">→</button><button class="circle-control" id="brand-pause" aria-label="${paused?'Reanudar':'Pausar'} animación">${paused?'▶':'Ⅱ'}</button></div></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">DESCUBRE MÁS</span><h2>Cada marca, un mundo.</h2></div></div><div class="brand-art-grid">${brands.map(b=>`<a href="#tienda?marca=${b.name}"><img src="${asset('Propuestas web/Productos/'+b.art)}" alt="Conoce los productos de ${b.name}" loading="lazy"><span>Explorar ${b.name} <b>↗</b></span></a>`).join('')}</div></section>`}
function showBrand(index){brandIndex=(index+brands.length)%brands.length;const b=brands[brandIndex],prefix='Propuestas web/Productos/'+b.folder+'/';const stage=document.getElementById('brand-stage');if(!stage)return;stage.innerHTML=`<div class="brand-slide" style="--brand-bg:${b.color}"><div class="shell brand-scene"><div class="brand-copy"><span class="eyebrow">${String(brandIndex+1).padStart(2,'0')} / NUESTRAS MARCAS</span><img class="scene-logo" src="${brandLogo(b.name)}" alt="${b.name}"><h2>${b.title.replace('\n','<br>')}</h2><p>${b.text}</p><a class="button navy" href="#tienda?marca=${b.name}">Descubrir ${b.name} ↗</a></div><button type="button" class="brand-visual" data-brand-next aria-label="Ver siguiente marca"><img class="scene-back" src="${asset(prefix+b.background)}" alt=""><img class="scene-splash" src="${asset(prefix+b.splash)}" alt=""><img class="scene-bottle" src="${asset(prefix+b.bottle)}" alt=""><img class="scene-detail" src="${asset(prefix+b.detail)}" alt=""><span class="scene-next-hint">Siguiente marca ↗</span></button></div></div>`;document.querySelectorAll('[data-brand-index]').forEach(el=>{const current=Number(el.dataset.brandIndex)===brandIndex;el.classList.toggle('active',current);el.setAttribute('aria-pressed',current)});document.querySelector('.brand-experience').classList.toggle('paused',paused)}
function startCarousel(){clearInterval(carouselTimer);const progress=document.querySelector('.brand-progress span');if(progress){progress.style.animation='none';void progress.offsetWidth;progress.style.animation=paused?'none':'brandProgress 4s linear infinite'}if(!paused)carouselTimer=setInterval(()=>{const exp=document.querySelector('.brand-experience');if(!document.hidden&&exp&&!productDialog.open&&!cartDialog.open)showBrand(brandIndex+1)},4000)}

const faqs=[['¿Cómo compro en la tienda?','Elige un producto, selecciona su presentación y cantidad, y añádelo al carrito. Completa los datos de entrega y factura, revisa el pedido y envíalo por WhatsApp. Nuestro equipo confirmará disponibilidad y pago.'],['¿Cómo se calcula el precio de la tienda?','El precio web es el importe que pagas por la presentación elegida. La referencia comparativa se calcula un 30 % por encima del precio web y no representa un precio anterior de venta. El carrito suma únicamente el precio web.'],['¿El envío es gratuito?','El envío se coordina según el destino y el pedido. El costo y la fecha de entrega se confirman antes del pago; no están incluidos en el total de productos.'],['¿Puedo solicitar factura?','Sí. En el pedido puedes indicar el nombre o razón social y el NIT o CI para la facturación.'],['¿Tienen presentaciones para empresas?','Sí. En Institucional encontrarás formatos de 5 litros. Para volúmenes, adjudicaciones, fichas técnicas o condiciones comerciales, solicita atención a empresas.'],['¿Puedo pagar dentro de la página?','Por el momento, el pedido se envía por WhatsApp y el pago se coordina con el equipo comercial. No se solicitan datos de tarjetas en este sitio.']];
function about(){return `<section class="about-hero shell"><div><span class="eyebrow">MULTI INTERNACIONAL S.R.L.</span><h1>Hechos aquí.<br>Para cuidar<br><em>lo que importa.</em></h1><p>Somos una empresa boliviana dedicada a la fabricación y comercialización de productos de limpieza para el hogar y de cuidado personal.</p><a class="text-link" href="#productos">Conoce nuestras marcas ↗</a></div><img src="${asset('Propuestas web/Nosotros/Foto empresa.png')}" alt="Instalaciones de Multi Internacional" fetchpriority="high"></section><section class="values-section"><div class="shell values-grid"><article><span class="eyebrow">01 / NUESTRA MISIÓN</span><h2>Cuidar el bienestar<br>de cada familia.</h2><p>Fabricar productos de limpieza e higiene personal de alta calidad, que brinden soluciones efectivas y seguras para los hogares bolivianos, contribuyendo al bienestar familiar.</p></article><article><span class="eyebrow">02 / NUESTRA VISIÓN</span><h2>Crecer con calidad<br>e innovación.</h2><p>Ser la empresa líder en Bolivia en la fabricación de productos de limpieza y cuidado personal, destacando por nuestra innovación continua, calidad superior y compromiso con el cliente y el medio ambiente.</p></article></div></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">DETRÁS DE CADA PRODUCTO</span><h2>El lugar donde todo comienza.</h2></div></div><div class="company-gallery">${[1,2,3].map((n)=>`<figure><img src="${asset('Propuestas web/Nosotros/Foto empresa '+n+'.png')}" alt="Instalaciones y almacenes de la empresa, vista ${n}" loading="lazy"></figure>`).join('')}</div><p class="company-copy">Nuestros procesos de producción cumplen con estrictos estándares de calidad, seguridad e higiene industrial, y están alineados con un firme compromiso hacia la sostenibilidad y el respeto al medio ambiente.</p></section><section class="faq-section"><div class="shell faq-grid"><div><span class="eyebrow">TE AYUDAMOS</span><h2>Respuestas<br>sin vueltas.</h2><p>Todo lo que necesitas saber antes de tu compra.</p><a href="${wa('Hola, tengo una consulta sobre los productos de Archer.')}" target="_blank" rel="noopener" class="text-link">Hablar con el equipo ↗</a></div><div>${faqs.map(([q,a])=>`<details class="faq"><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></div></section>`}
function institutional(){return `<section class="institution-hero"><div class="shell"><div><span class="eyebrow">SOLUCIONES PARA EMPRESAS</span><h1>Gran formato.<br><em>Grandes resultados.</em></h1><p>Limpieza institucional en presentaciones de 5 litros. Para el abastecimiento de tu empresa, equipos de limpieza y procesos de compra.</p><a class="button" href="#institucional-solicitud" data-scroll-request>Solicitar propuesta comercial ↗</a><span class="institution-tag">EMPRESAS · INSTITUCIONES · ADJUDICACIONES</span></div><div class="institution-packs"><img src="${asset('productos png/Institucional png/ARCHER Antigrasa 1 x 5 Lt.png')}" alt="Antigrasa Archer 5 litros"><img src="${asset('productos png/Institucional png/ARCHER Limpia Hornos 1 x 5 Lt.png')}" alt="Limpia hornos Archer 5 litros"><span>5<span>LITROS</span></span></div></div></section><section class="shell section"><div class="section-heading"><div><span class="eyebrow">EL FORMATO DE TU OPERACIÓN</span><h2>Abastece tu equipo.</h2></div><a class="text-link" href="#tienda?categoria=institucional">Ver todos los formatos de 5 L ↗</a></div><div class="product-grid">${C.filter(p=>p.institutional&&['vajillero','antigrasa','limpia-hornos','limpia-vidrios','germasep','classic-jabon'].includes(p.id)).map(p=>card(p,true)).join('')}</div><div class="technical-note"><b>Documentación para tu requerimiento</b><p>Solicita fichas técnicas, indicaciones de uso, compatibilidad de superficies y documentación comercial para tu proceso de compra. Las diluciones y tiempos de contacto deben corresponder a la ficha de cada producto.</p></div></section>${businessForm('institucional-solicitud','Cuéntanos qué necesita tu empresa.','Institucional')}`}
function businessForm(id,title,type){return `<section id="${id}" class="business-section"><div class="shell business-grid"><div><span class="eyebrow">ATENCIÓN COMERCIAL</span><h2>${title}</h2><p>Comparte tu requerimiento y coordinemos productos, volúmenes y condiciones.</p><a class="text-link" href="mailto:ventas@archer.com.bo">ventas@archer.com.bo</a></div><form class="business-form" data-type="${type}"><div class="form-grid"><label class="field">Empresa / institución<input name="company" required maxlength="120" autocomplete="organization"></label><label class="field">Nombre de contacto<input name="name" required maxlength="100" autocomplete="name"></label><label class="field">Celular<input name="phone" required type="tel" pattern="[+0-9 ()-]{8,20}" maxlength="20"></label><label class="field">Ciudad / país<input name="place" required maxlength="100"></label><label class="field wide">Productos, cantidades y requerimiento<textarea name="request" required rows="4" maxlength="1200" placeholder="Indica presentaciones, volumen y, si corresponde, la referencia de la adjudicación."></textarea></label></div><button class="button navy" type="submit">Preparar solicitud ↗</button><p class="micro">Revisarás el mensaje antes de compartirlo por WhatsApp.</p><div class="business-result" aria-live="polite"></div></form></div></section>`}
function international(){return `<section class="international-hero"><div class="shell"><span class="eyebrow">NEGOCIOS INTERNACIONALES</span><h1>Llevamos calidad.<br><em>Llevamos confianza.</em></h1><p>En Archer, expandimos fronteras para llevar productos de limpieza de alta calidad a más empresas y hogares en todo el mundo.</p><a class="button white" href="#internacionales-contacto" data-scroll-request>Construyamos nuevas oportunidades ↗</a><div class="international-markets"><span>PRESENCIA INTERNACIONAL</span><strong>Chile</strong><strong>Perú</strong><strong>Paraguay</strong></div></div></section><section class="shell section"><div class="section-heading"><div><span class="eyebrow">RELACIONES QUE TRASCIENDEN FRONTERAS</span><h2>Nuestros mercados.</h2></div><p class="section-description">Archer tiene presencia en 3 países de Latinoamérica, ofreciendo soluciones de limpieza con calidad, innovación y compromiso.</p></div><div class="market-grid">${[['01','Chile','Soluciones de limpieza eficientes que cumplen con los más altos estándares de calidad.'],['02','Perú','Llevamos nuestros productos a miles de hogares y empresas peruanas con calidad y confianza.'],['03','Paraguay','Comprometidos con la limpieza y el bienestar de las familias paraguayas.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="company-copy">Seguimos creciendo y construyendo relaciones sólidas y basadas en la confianza, la calidad y el servicio.</p></section><section class="values-section"><div class="shell"><span class="eyebrow">NUESTRA FORTALEZA</span><h2>Capacidad para crecer juntos.</h2><div class="strength-grid">${[['Garantía y calidad','Todos nuestros productos cuentan con certificación AGEMED vigente y sus respectivas fichas técnicas.'],['Experiencia internacional','Más de 10 años exportando y posicionando nuestros productos en el exterior.'],['Capacidad operativa','Contamos con la infraestructura y capacidad de producción para atender nuevos pedidos de gran escala.'],['Servicio de maquila (OEM)','Desarrollamos y fabricamos tu línea de productos bajo el formato de marca privada.'],['Producción y control','Laboratorios propios y estrictos controles que aseguren la eficacia de los productos.'],['Logística eficiente','Procesos logísticos optimizados para cumplir con entregas seguras y puntuales.']].map(([t,d])=>`<article><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>${businessForm('internacionales-contacto','Construyamos nuevas oportunidades.','Negocios internacionales')}`}

function route(){clearInterval(carouselTimer);productDialog.close();cartDialog.close();const hash=location.hash.slice(1)||'inicio';if(hash==='main'){main.focus();return}if(['institucional-solicitud','internacionales-contacto'].includes(hash)){document.getElementById(hash)?.scrollIntoView({behavior:'smooth'});return}const [name,qs]=hash.split('?'),params=new URLSearchParams(qs);document.getElementById('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+name));const pages={inicio:home,nosotros:about,productos:brandsPage,internacionales:international,institucional:institutional,tienda:()=>shop(params),pedido:checkout};main.innerHTML=(pages[name]||home)();document.title=({inicio:'Archer | Limpieza y cuidado',nosotros:'Nosotros | Archer',productos:'Nuestras marcas | Archer',internacionales:'Negocios internacionales | Archer',institucional:'Limpieza institucional | Archer',tienda:'Compra online | Archer',pedido:'Tu pedido | Archer'}[name]||'Archer');if(name==='tienda'){shopCategory=params.get('categoria')||'todos';filterShop()}if(name==='productos'){showBrand(brandIndex);startCarousel()}window.scrollTo({top:0,behavior:'instant'});saveCart()}
document.addEventListener('click',e=>{
 const close=e.target.closest('[data-close]');if(close){close.closest('dialog').close();return}
 const product=e.target.closest('[data-product]');if(product){openProduct(product.dataset.product,product.dataset.institutional==='true');return}
 if(e.target.closest('.cart-toggle')){openCart();return}
 if(e.target.closest('.menu-toggle')){const open=document.getElementById('nav').classList.toggle('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded',open);return}
 if(e.target.closest('[data-checkout],[data-close-link]')){productDialog.close();cartDialog.close()}
 if(e.target.closest('#add-product')){const q=Number(document.getElementById('product-qty').value);if(!Number.isInteger(q)||q<1||q>99){document.getElementById('product-qty').reportValidity();return}addCart(selectedVariant.id,q);productDialog.close();return}
 const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(r=>r.variantId!==remove.dataset.remove);saveCart();openCart();return}
 const qty=e.target.closest('[data-qty]');if(qty){const row=cart.find(r=>r.variantId===qty.dataset.qty);if(row)row.quantity=Math.max(1,Math.min(99,row.quantity+Number(qty.dataset.delta)));saveCart();openCart();return}
 const cat=e.target.closest('[data-category]');if(cat){shopCategory=cat.dataset.category;filterShop();const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('categoria',shopCategory);history.replaceState(null,'','#tienda?'+q);return}
 if(e.target.closest('#reset-filters')){shopCategory='todos';document.getElementById('search').value='';document.getElementById('brand-filter').value='todas';document.getElementById('sort-filter').value='recommended';filterShop();history.replaceState(null,'','#tienda');return}
 const brand=e.target.closest('[data-brand-index]');if(brand){showBrand(Number(brand.dataset.brandIndex));startCarousel();return}
 if(e.target.closest('[data-brand-prev]')){showBrand(brandIndex-1);startCarousel();return}if(e.target.closest('[data-brand-next]')){showBrand(brandIndex+1);startCarousel();return}
 if(e.target.closest('#brand-pause')){paused=!paused;const b=document.getElementById('brand-pause');b.textContent=paused?'▶':'Ⅱ';b.setAttribute('aria-label',paused?'Reanudar animación':'Pausar animación');document.querySelector('.brand-experience').classList.toggle('paused',paused);startCarousel();return}
 const scroll=e.target.closest('[data-scroll-request]');if(scroll){e.preventDefault();document.querySelector(scroll.getAttribute('href'))?.scrollIntoView({behavior:'smooth'});return}
 if(e.target.closest('#edit-order'))restoreOrder();
});
document.addEventListener('change',e=>{if(e.target.id==='variant-select'){selectedVariant=selectedProduct.variants.find(v=>v.id===e.target.value);updateVariant()}if(['brand-filter','sort-filter'].includes(e.target.id)){filterShop();if(e.target.id==='brand-filter'){const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('marca',e.target.value);history.replaceState(null,'','#tienda?'+q)}}if(e.target.id==='invoice')toggleInvoice()});
document.addEventListener('input',e=>{if(e.target.id==='search')filterShop();if(e.target.closest('#order-form')&&document.getElementById('invoice'))orderDraft=Object.fromEntries(new FormData(document.getElementById('order-form')))});
document.addEventListener('submit',e=>{if(e.target.id==='order-form'){e.preventDefault();if(!cart.length){route();return}const data=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(data))data[key]=data[key].trim();for(const key of ['name','phone','department','city','address','location',...(data.invoice==='si'?['business','taxId']:[])])if(!data[key]){toast('Completa los datos obligatorios.');return}reviewOrder(data)}if(e.target.matches('.business-form')){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const msg=`SOLICITUD · ${e.target.dataset.type}\nEmpresa: ${data.company}\nContacto: ${data.name}\nTeléfono: ${data.phone}\nCiudad / país: ${data.place}\nRequerimiento: ${data.request}`;e.target.querySelector('.business-result').innerHTML=`<p>Revisa tu solicitud para Archer (77226763):</p><pre>${esc(msg)}</pre><a class="button whatsapp" href="${wa(msg)}" target="_blank" rel="noopener">Enviar solicitud por WhatsApp ↗</a>`}});
for(const dlg of [productDialog,cartDialog])dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
cartDialog.addEventListener('close',()=>{if(location.hash.startsWith('#pedido'))restoreOrder()});
window.addEventListener('hashchange',route);route();

// Optional structured access to the same catalogue and local cart used by the UI.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'search_archer_catalog',title:'Buscar productos Archer',description:'Consulta familias y variantes con precios en bolivianos. No modifica el carrito.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>100)throw Error('Consulta inválida');const q=input.query.toLocaleLowerCase('es');return C.filter(p=>(p.brand+' '+p.name+' '+p.variants.map(v=>v.label).join(' ')).toLocaleLowerCase('es').includes(q)).map(p=>({id:p.id,name:p.brand+' '+p.name,variants:p.variants.map(v=>({id:v.id,label:v.label,priceCents:price(v),currency:'BOB'}))}))}});
 register({name:'read_archer_cart',title:'Consultar carrito',description:'Lee la selección local y los totales. No envía pedidos ni datos personales.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {items:cart.map(r=>({...r})),...S.totals(cart,C,CFG.referenceMarkupPercent),currency:'BOB',shipping:'Por coordinar'}}});
 register({name:'add_archer_cart_items',title:'Añadir productos al carrito',description:'Añade variantes al carrito local y abre el carrito para revisión. No realiza pagos ni envía mensajes.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:30,items:{type:'object',properties:{variantId:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['variantId','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.items)||input.items.length<1||input.items.length>30||input.items.some(r=>!r||!lookup(r.variantId)||!Number.isInteger(r.quantity)||r.quantity<1||r.quantity>99))throw Error('Variantes o cantidades inválidas; el carrito no se modificó');for(const r of input.items)addCart(r.variantId,r.quantity);openCart();return {items:cart.map(r=>({...r})),...S.totals(cart,C,CFG.referenceMarkupPercent),currency:'BOB'}}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
